import{_ as e,o as a,c as t,aw as l}from"./chunks/framework.DLufY-ao.js";const d=JSON.parse('{"title":"Наследование","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/theory/programming/oop/principles/inheritance.md","filePath":"wiki/dev-commit/theory/programming/oop/principles/inheritance.md"}'),r={name:"wiki/dev-commit/theory/programming/oop/principles/inheritance.md"};function o(n,i,s,c,p,m){return a(),t("div",null,[...i[0]||(i[0]=[l('<h1 id="наследование" tabindex="-1">Наследование <a class="header-anchor" href="#наследование" aria-label="Permalink to &quot;Наследование&quot;">​</a></h1><ul><li><strong>Наследование</strong> - описание нового класса на основе уже существующего с частично или полностью заимствующейся функциональностью</li><li>Наследование транзитивно: класс может наследоваться от другого класса, который наследуется от третьего, и так далее вплоть до базового класса (Object). Наследник может переопределить какие-то методы и поля чтобы изменить поведение по умолчанию</li><li>SuperClass: базовый, родительский, предок, надкласс, супер класс</li><li>SubClass: наследник, дочерний, потомок, подкласс, суб класс, производный</li><li>Подкласс должен являться более специализированной версией супер-класса</li><li><strong>Множественное наследование</strong> - у одного подкласса существует сразу несколько супер-классов</li></ul><h2 id="когда-использовать-наследование" tabindex="-1">Когда использовать наследование <a class="header-anchor" href="#когда-использовать-наследование" aria-label="Permalink to &quot;Когда использовать наследование&quot;">​</a></h2><p>Испльзовать</p><ul><li>Класс-потомок использует большинство свойств и методов базового класса</li><li>С классом-потомком удобно работать по принципам SOLID</li></ul><p>Не использовать</p><ul><li>Реализация класса-потомка сильно отличается от наследуемого класса</li><li>Приходится переопределять методы и свойства у класса-потомка (что некорректно по SOLID)</li><li>Класс-потомок не использует методы и свойства из базового класса или их использование крайне мало</li></ul>',7)])])}const h=e(r,[["render",o]]);export{d as __pageData,h as default};
